// from src/locales/ja/blog.ts. Body + FAQs for article 'image-to-pdf-guide' (ja).
// This file is the single source for this article's ja body text.
import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "<p>PDFは、複数の画像を1つの書類として共有する最も確実な方法です。どの端末でも同じように開け、印刷も安定し、ページの順番が入れ替わることもありません。</p>\n<p>画像をPDFにするには、以前はソフトのインストールやWebサイトへのアップロードが必要でした。今はブラウザででき、画像が端末から出ることもありません。</p>\n<p>この記事では、作業全体を解説します。ページサイズ、向き、余白、画質、そしてPDFをプロらしく見せる小さな判断まで学べます。</p>\n<h2 id=\"what-is-image-to-pdf\">画像をPDFに変換するとは</h2>\n<p>画像をPDFに変換すると、1枚以上の画像ファイルからPDF書類が作られます。各画像が1ページになり、ページは自分で決めた順番のまま保たれます。</p>\n<p>結果は、誰でも開ける1つのファイルです。スマホ、パソコン、プリンターはすべてPDFを読め、レイアウトは設定どおりに保たれます。</p>\n<p>用途は、スキャンした書類、身分証の写真、レシート、宿題、ポートフォリオ、写真アルバムなどです。複数の画像が1つにまとまるべき場面では、PDFが最もすっきりした送り方です。</p>\n<p>CompressMyPicのツールは、PDFをブラウザ内でローカルに作ります。スキャンや身分証の写真がサーバーへアップロードされることはないので、機密書類にも安心です。</p>\n<h2 id=\"why-pdf\">画像のまま送るよりPDFがよい理由</h2>\n<p>20枚の画像が入ったフォルダは、送るのが面倒で、どれかを見失いやすいです。1つのPDFなら、すべてが1つのファイル名のもと、順番どおりにまとまります。</p>\n<p>PDFはレイアウトも守ります。チャットアプリに貼った画像は圧縮されたり並び替えられたりしますが、PDFはページ順とサイズを正確に保ちます。</p>\n<p>印刷も大きな理由です。PDFは1ページに1枚の画像を予測可能なサイズで印刷しますが、ばらばらの画像を印刷すると、思わぬ結果になりがちです。</p>\n<p>さらに、多くの公的システムはPDFアップロードしか受け付けません。ビザ申請、大学のポータル、税務サイトは書類を求めており、写真ファイルでは通りません。このツールがそのギャップを埋めます。</p>\n<h2 id=\"page-sizes-explained\">ページサイズ：A4・レター・画像に合わせる</h2>\n<p>A4は世界のほとんどの地域の標準ページサイズです。210×297ミリで、書類、フォーム、印刷して提出するものの既定の選択です。</p>\n<p>USレターはA4より少し幅広く、少し短いサイズです。アメリカとカナダの標準なので、送り先がアメリカの場合や、フォームがレターを指定している場合に使います。</p>\n<p>画像サイズに合わせる設定では、ページが各画像とぴったり同じサイズになります。余白も切り取りもなく、画像がページいっぱいに広がります。</p>\n<p>印刷するPDFや公的システムへ提出するPDFには、A4かレターを選んでください。写真集やスキャンの保管には、画像サイズに合わせる設定が向いています。</p>\n<h2 id=\"orientation-and-fit\">向きと自動判別</h2>\n<p>向きは、ページが縦か横かを決めます。縦長の写真は縦のページに、横長の写真は横のページに置くのが自然です。</p>\n<p>自動判別は各画像を読み取り、合う向きを自動で選びます。縦と横が混ざったバッチでも、すべてのページが自動で正しいレイアウトになります。</p>\n<p>画像サイズに合わせる設定を選ぶと、向きの選択は無効になります。ページサイズが画像に合わせられるので、別に向きを選ぶ意味がなくなるからです。</p>\n<p>スキャンした書類は、ほぼ常に縦向きが正解です。スクリーンショットや横長の写真は、1つのレイアウトに無理にそろえるのではなく、自動判別に任せましょう。</p>\n<h2 id=\"contain-vs-cover\">全体表示と全面表示</h2>\n<p>全体表示は、画像全体をページ内に収めます。端に余白が残ることもありますが、切り取りは一切ありません。書類の一部が切れる心配がありません。</p>\n<p>全面表示はページ全体を埋め、はみ出した部分を切り取ります。ページは端までいっぱいに見えますが、画像の端が切り取られる場合があります。</p>\n<p>書類、身分証、レシートには、常に全体表示を使ってください。署名が切れたり、身分証の隅が欠けたりすると、申請が却下されることがあります。</p>\n<p>写真アルバムやプレゼン資料には、全面表示のほうが見栄えがよいです。端までいっぱいのレイアウトは意図的に見え、写真が少し切れても問題になりにくいです。</p>\n<h2 id=\"margins-explained\">余白：なし・小・中</h2>\n<p>余白なしは、画像をページの端まで配置します。画像サイズに合わせる設定や全面写真に合い、余白があるとミスに見える場合に使います。</p>\n<p>小さい余白は、画像の周りに細い白い枠を付けます。画面でも見栄えがよく、印刷時も画像がページの端から離れて安心です。</p>\n<p>中くらいの余白はさらに広い枠を付けます。正式な書類や、印刷してファイリングするものに向いています。余白が広いと、プリンターの端で画像が切れにくくなります。</p>\n<p>プリンターは紙の端まで印刷できないので、余白なしのPDFは紙の上で画像の端が少し切れることがあります。印刷するものには、少なくとも小さい余白を使いましょう。</p>\n<h2 id=\"quality-slider\">PDFの画質スライダー</h2>\n<p>画質スライダーは、PDF内の画像がどれだけ圧縮されるかを調整します。画質が高いほど細部が残ってPDFは大きくなり、低いほどファイルは小さくなります。</p>\n<p>スキャンした書類や身分証の写真は、画質を高く保ってください。低画質では文字や細かい印刷がすぐぼやけ、ぼやけた身分証は却下されます。</p>\n<p>画面で見る写真集なら、中くらいの画質で十分です。スマホやパソコンでは画像はきれいに見え、PDFもメールで送れるサイズに収まります。</p>\n<p>生成後は最終的なファイルサイズを確認してください。メールに添付できないほど大きい場合は、画質を1段階下げてもう一度生成します。</p>\n<h2 id=\"reordering-pages\">生成前のページ並び替え</h2>\n<p>ページ順は書類の順番そのものなので、生成前に正しく整えてください。ツールにはページ順リストがあり、ドラッグで正しい順序に並べ替えられます。</p>\n<p>リストを確認したあとで、写真を追加することもできます。新しい画像はキューの末尾に入り、他のページと同じようにドラッグして配置できます。</p>\n<p>公的書類の場合は、順番を2回確認してください。ページが完璧でも、順番がばらばらなビザ申請は雑に見えてしまいます。</p>\n<p>重複したページや上下逆さまのページも、この時点で取り除きます。あとでPDFを作り直すより、今直すほうがはるかに簡単です。</p>\n<h2 id=\"heic-to-pdf\">HEIC写真を直接PDFへ</h2>\n<p>iPhoneの写真は、別に変換する手順なしで、そのままPDF作成ツールに入れられます。ツールがブラウザ内でHEICファイルをデコードし、JPGと同じようにページに配置します。</p>\n<p>iPhoneユーザーには、1つの手順が省けるので便利です。HEICをJPGに変換してからPDFを作るのではなく、HEICファイルをドロップして1回生成するだけです。</p>\n<p>デコードした画像は、解像度も向きもそのまま保たれます。縦の写真は縦のまま、横の写真は横のままです。自動の向き処理のおかげです。</p>\n<p>HEICファイルが読み込めない場合は、先に<a href=\"/ja/heic-jpg-henkan/\">HEICからJPGへの変換ツール</a>でJPGに変換してから、PDFに追加してください。この2段階の方法なら、どのファイルでもうまくいきます。</p>\n<h2 id=\"transparency-in-pdf\">PDF内の透過</h2>\n<p>透明なPNGやWebP画像は、PDF内では白い背景になります。PDFは画像ファイルと同じようには透過を扱わないため、ツールが透けた部分を白で埋めます。</p>\n<p>ほとんどの書類では、白がまさに正解です。白背景の透明ロゴはすっきり見え、どのプリンターでもきれいに印刷できます。</p>\n<p>色付きのページに透明画像が必要な場合は、先にJPGへ変換して、合うマット色を指定してください。<a href=\"/ja/png-jpg-henkan/\">PNGからJPGへの変換ツール</a>で塗りつぶし色を選べます。</p>\n<p>スキャンした書類に透過はありません。この話が関係するのは、ロゴ、ステッカー、グラフィックだけです。普通の写真では、まったく気にしなくて構いません。</p>\n<h2 id=\"filenames-and-downloads\">ファイル名とPDFのダウンロード</h2>\n<p>出力ファイル名は、保存前に自由に変えられます。passport-application.pdfのような分かりやすい名前は、あとで探すときに汎用的な名前よりずっと便利です。</p>\n<p>生成中は「Encoding page X of Y」という進捗メッセージが表示されます。20ページのPDFでも、生成は数秒で終わります。数分はかかりません。</p>\n<p>ブラウザのダウンロードダイアログが消えてしまったら、ダウンロードフォルダを確認してください。ダイアログを誤って閉じても、ファイルは自動でそこに保存されています。</p>\n<p>完成したPDFは、送る前に一度開いてください。ページ数、順番、最も小さい文字の読みやすさを確認してから、自信を持って共有しましょう。</p>\n<h2 id=\"privacy-and-safety\">プライバシー：身分証やレシートも安全</h2>\n<p>PDFはブラウザ内で完全に生成されるので、パスポート、身分証、税務レシートがどこにもアップロードされません。自分の最も機密性の高い書類にも、このツールは安全です。</p>\n<p>生成したPDFに透かし、フッターのロゴ、ページの刻印は付きません。書類には、配置した自分の画像だけが含まれます。</p>\n<p>1つだけ注意点があります。PDFの生成では、画像内のEXIFメタデータは除去されません。写真にGPSタグが付いている場合は、先にメタデータツールで除去することを検討してください。</p>\n<p>ダウンロード後、PDFは自分の端末にだけ存在します。タブを閉じれば、サーバーが関わっていなかったので、どこにもコピーは残りません。</p>\n<h2 id=\"pdfs-for-school\">学校や大学用のPDF</h2>\n<p>学生は、宿題のスキャンから論文の提出まで、常にPDFを作ります。1つのPDFならすべてのページが順番どおりにまとまり、採点者が何十もの提出物を読むときに重要です。</p>\n<p>課題には、A4サイズで全体表示、小さい余白の組み合わせを使ってください。画面でも見栄えがよく、採点用に印刷してもきれいです。</p>\n<p>手書きのスキャンでは、画質スライダーを高く保ってください。低画質では手書きがすぐぼやけ、採点者が読めない答えは採点できません。</p>\n<p>ファイル名には、自分の名前と課題名を入れましょう。ahmed-essay-3.pdfのような名前なら、先生が正しく整理でき、他の学生と混同しません。</p>\n<p>提出前にファイルサイズを確認してください。大学のポータルは5MBや10MBの上限を設けていることが多く、高画質スキャンの長いPDFは上限を超える場合があります。</p>\n<h2 id=\"pdfs-for-work\">仕事やビジネス用のPDF</h2>\n<p>請求書、契約書、レシートは、ビジネスではすべてPDFでやり取りされます。1つの書類は、ばらばらの画像フォルダより、整理、転送、保管が簡単です。</p>\n<p>請求書には、A4サイズで全体表示、中くらいの余白を使ってください。正式なレイアウトはプロらしく見え、余白が内容をプリンターの端から守ります。</p>\n<p>レシートには、画像サイズに合わせる設定がよく合います。レシートは形がさまざまなので、各ページがレシートにぴったり合い、無駄な余白がありません。</p>\n<p>送ったPDFはすべてコピーを残してください。取引先と月ごとに整理した送信フォルダがあれば、質問があったときに書類をすぐ見つけられます。</p>\n<p>機密性の高いビジネス書類では、PDFがローカルで生成されることを忘れないでください。契約書や財務記録は、変換中に端末から出ることはありません。</p>\n<h2 id=\"scanning-tips\">きれいなPDFのためのスキャンのコツ</h2>\n<p>きれいなスキャンがきれいなPDFを作ります。悪いスキャンは、どんな設定でも救えません。ページをスキャナーに平らに置き、端をそろえ、折れや影がないか確認してください。</p>\n<p>文字のある書類は200DPI以上でスキャンしてください。解像度が低いと小さな文字がぼやけ、PDFでシャープにすることはできません。</p>\n<p>印鑑、署名、色付きのハイライトがある書類は、カラーでスキャンしてください。グレースケールは小さくなりますが、真正性を証明する色情報が失われます。</p>\n<p>重要な作業の前には、スキャナーのガラスを掃除してください。ほんの小さなホコリでも、すべてのページに黒い点として現れ、公的書類では不真面目に見えます。</p>\n<p>PDFに追加する前に、各スキャンをプレビューしてください。横向きや逆さまのページは、スキャン段階なら簡単に直せます。あとで直すのは面倒です。</p>\n<h2 id=\"sharing-and-storing-pdfs\">完成したPDFの共有と保管</h2>\n<p>完成したPDFは、メール、チャット、クラウドストレージで簡単に共有できます。1つのファイルが1つの添付ファイルとして送られ、フォルダが途中で欠ける心配がありません。</p>\n<p>メールで送る前にファイルサイズを確認してください。ほとんどのメールサービスは添付ファイルを20MBから25MBまでに制限しており、高画質スキャンの長いPDFは上限を超える場合があります。</p>\n<p>大きなPDFは、添付ではなくクラウドリンクで共有しましょう。ドライブにアップロードしてリンクを共有すれば、相手はサイズの問題なくダウンロードできます。</p>\n<p>完成したPDFは、目的と日付で整理したフォルダに保管してください。2026-11-visa-documentsのようなフォルダは数年後でも見つけやすく、stuffというフォルダはそうはいきません。</p>\n<p>PDFを生成したあとも、元の画像は残しておきましょう。相手が別のページサイズや小さいファイルを求めた場合、再スキャンなしで原本から作り直せます。</p>\n<h2 id=\"pdfs-for-travel\">旅行書類のPDF</h2>\n<p>旅行書類は、1つのPDFにまとめてスマホに入れておくのが便利です。パスポートのコピー、ビザ、ホテルの予約、航空券が1つのファイルにあれば、国境やチェックインカウンターですぐ見つかります。</p>\n<p>A4サイズで全体表示を使い、すべての書類がページに完全に収まるようにしてください。パスポート番号の切り取りやビザの印鑑の欠落は、旅行用PDFで最も多い問題です。</p>\n<p>旅行書類は、画質スライダーを高く保ってください。ぼやけたパスポートのコピーは国境で却下されることがありますが、くっきりしたコピーは問題なく通ります。</p>\n<p>PDFはスマホとクラウドストレージの両方に保存してください。スマホを紛失したり盗まれたりしても、クラウドのコピーがあればどの端末からでも書類にアクセスできます。</p>\n<p>元の画像も残しておきましょう。係員が別の形式を求めた場合、原本があれば再スキャンなしでPDFを作り直せます。</p>\n<p>書類を作る準備はできましたか。<a href=\"/ja/gazou-pdf-henkan/\">画像をPDFに変換するツール</a>を開いて画像をドロップし、生成してください。</p>\n<p>手順版は<a href=\"/ja/blog/gazou-pdf-henkan-yarikata/\">画像をPDFに変換する方法</a>、JPGとPNGのどちらを使うかは<a href=\"/ja/blog/jpg-pdf-vs-png-pdf/\">JPGをPDFに変換 vs PNGをPDFに変換</a>をご覧ください。画像のサイズを先に整えたい場合は、<a href=\"/ja/gazou-henkan/\">画像変換ツール</a>が使えます。</p>";

export const FAQS: BlogArticleFaq[] = [{"question":"1つのPDFに何枚の画像を入れられますか？","answer":"ツールに固定のページ数制限はなく、数十枚のバッチも問題なく動作します。ただし非常に長い書類は生成に時間がかかり、ファイルも大きくなります。メールで送る場合は、枚数をほどほどにしてください。50枚の写真アルバムなら、2つのPDFに分けるのがよいでしょう。"},{"question":"PDFはどの端末でも同じように見えますか？","answer":"はい、それがPDFの最大の強みです。設定したページサイズ、順番、レイアウトは、スマホ、パソコン、プリンターでそのまま保たれます。相手がどのアプリで開いても、自分が見たものとまったく同じものが見えます。"},{"question":"すでにあるPDFと画像を1つの書類にまとめられますか？","answer":"このツールではできません。画像からPDFを作る専用のツールだからです。すでにPDFがある場合は、専用のPDF結合ツールで、新しい画像PDFと組み合わせてください。まず画像PDFを生成し、そのあと2つのファイルを結合します。"},{"question":"生成したPDFのファイルが大きすぎるのはなぜですか？","answer":"PDFのサイズは、画像の枚数と画質スライダーで決まります。高画質のスキャンが何ページも重なると、すぐに大きくなります。画質スライダーを1段階下げるか、画像の枚数を減らしてもう一度生成してください。写真は中画質でも、スキャンよりずっとよく圧縮できます。"},{"question":"インターネットがなくても画像をPDFに変換できますか？","answer":"ページが一度ブラウザに読み込まれれば、PDF生成はローカルで動き、インターネットは不要です。接続が必要なのは、最初にページを開くときだけです。そのあとは、タブを閉じるまでオフラインでPDFを作れます。"},{"question":"スキャンした書類のPDFに最適なページサイズは何ですか？","answer":"ほとんどの国ではA4が最適な既定値です。プリンターや公的システムがA4を前提としているからです。送り先がアメリカやカナダの場合、またはその旨が明記されている場合に限り、USレターを使ってください。画像サイズに合わせる設定は写真向きで、書類には向きません。ページサイズが画像ごとに変わってしまうからです。"}];
